def test_dca_config():
    header = b"\xa8*\xf8g\x12/\x06\x00<\x00\x00\x00<\x00\x00\x00"
    data = b"P\xeb\xf6}\xceD\x124Vx\x90\x12\x08\x00E\x00\x00$\x00\x00@\x00\xff\x11\xb7\xa5\xc0\xa8!\xb4\xc0\xa8!\x1e\x04\x00\x10\x00\x00\x10\x00\x00Z\xa5\t\x00\x00\x00\xaa\xee\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00"

    p = disspcap.Packet(data)
    assert p.dca_config
    assert p.dca_raw is None
    assert int(p.ts.timestamp()) == 0
    assert p.ts.microsecond == 0
    assert len(p) == 60

    ts_sec, ts_usec, caplen, origlen = struct.unpack("=IIII", header)
    assert ts_sec == 1744317096
    assert ts_usec == 405266
    assert caplen == 60
    assert origlen == 60

    p = disspcap.Packet(data, ts_sec, ts_usec)
    assert p.dca_config
    assert p.dca_raw is None
    assert int(p.ts.timestamp()) == ts_sec
    assert p.ts.microsecond == ts_usec


def test_dca_raw(dr1):
    header = b'\xa8*\xf8g5R\x06\x00\xe4\x05\x00\x00\xe4\x05\x00\x00'

    p = disspcap.Packet(dr1)
    assert p.dca_config is None
    assert p.dca_raw
    assert int(p.ts.timestamp()) == 0
    assert p.ts.microsecond == 0
    assert len(p) == 1508

    assert p.dca_raw.seq_id == 1
    assert p.dca_raw.byte_count == 0
    assert len(p.dca_raw.payload) == 1456


def test_dca_data(dr1):
    dd = disspcap.DcaData()
    dr1 = disspcap.Packet(dr1)


    dd.add(dr1.dca_raw)
    dd.convert_complex(True)

    arr = np.array(dd, copy=False, dtype=np.complex64)
    assert arr.shape == (364,)
